Change(genesis='66602cd0dec37d58d03eec9518ca805a7ac38ea912d2b0c366a0b67b4b9f50b6', deps=(), event=Decided(decision='boxerases', at=datetime(2026, 10, 9, 0, 0, 0), actor='assistant', title="Only the box writes an erasure, on the owner's act or a forget", body="An Erased line is appended by the box alone: when the owner asks through the gated tap, or when a forget takes the copies it caused. No verb of the secretary or the triage agent can write one, and a tab's post to the lines admits only a rename, an opening and a setup.", rationale='An injected secretary must not be able to erase the evidence of its own injection.', supersedes=()))